#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEditor;using ElDespacho;
public class FinalVisionProbe:MonoBehaviour {
 List<string> log=new List<string>();AccessController a;DespachoGame g;DeskMenus m;AccessPreferences P=>AccessPreferences.Current;const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 void Check(bool v,string t){log.Add((v?"PASS ":"FAIL ")+t);File.WriteAllLines("Logs/FinalVision/results.txt",log);}
 IEnumerator Tick(){a.Refresh();yield return null;yield return null;yield return new WaitForSecondsRealtime(.2f);Canvas.ForceUpdateCanvases();}
 IEnumerator Start(){Directory.CreateDirectory("Logs/FinalVision");yield return null;yield return null;a=AccessController.Instance;g=a.GetComponent<DespachoGame>();m=g.GetComponent<DeskMenus>();DeskPreferences.Current.tutorial=false;m.Resume();g.StartFromMenu();typeof(DespachoGame).GetMethod("ShowOffice",F).Invoke(g,null);yield return Tick();
 a.ShowSettings();a.OpenCategory("Visual");foreach(float scale in new[]{.75f,1f,1.25f,1.5f,1.75f}){P.textScale=scale;yield return Tick();var t=a.transform.Find("Accessibility").GetComponentsInChildren<Text>().First(t=>t.text=="Alto contraste");Check(t.fontSize==Mathf.RoundToInt(24*scale),"actual settings font "+scale);}
 P.textScale=1;P.interfaceScale=.8f;yield return Tick();var root=a.transform.Find("Accessibility");var row=root.GetComponentsInChildren<RectTransform>().First(t=>t.name=="Setting: Alto contraste");float h=row.rect.height,w=row.Find("Icon").GetComponent<RectTransform>().rect.width;int font=row.GetComponentInChildren<Text>().fontSize;P.interfaceScale=1.2f;yield return Tick();row=root.GetComponentsInChildren<RectTransform>().First(t=>t.name=="Setting: Alto contraste");Check(row.rect.height>h&&row.Find("Icon").GetComponent<RectTransform>().rect.width>w&&row.GetComponentInChildren<Text>().fontSize==font,"interface scale changes geometry not text");P.interfaceScale=.8f;yield return Tick();row=root.GetComponentsInChildren<RectTransform>().First(t=>t.name=="Setting: Alto contraste");Check(Mathf.Abs(row.rect.height-h)<1,"interface geometry reverses");
 a.ClosePanels();m.Resume();P.symbols=false;P.narration=false;P.independentColor=false;yield return Tick();a.SetReadingView(true);yield return Tick();int off=a.Snapshot().Count(t=>t.text.Contains(" / 100:"));P.independentColor=true;yield return Tick();Check(a.Snapshot().Count(t=>t.text.Contains(" / 100:"))>off,"indicator labels add actual value and status");P.independentColor=false;yield return Tick();Check(a.Snapshot().Count(t=>t.text.Contains(" / 100:"))==off,"indicator labels revert");a.SetReadingView(false);
 var fixture=new GameObject("FinalWiggle",typeof(RectTransform));var wig=fixture.AddComponent<Wiggle>();var rt=(RectTransform)fixture.transform;var timer=typeof(Wiggle).GetField("timer",F);DeskPreferences.Current.reduceMotion=false;P.reduceFlashes=false;timer.SetValue(wig,2.1f);yield return null;Check(rt.localScale!=Vector3.one||rt.localRotation!=Quaternion.identity,"normal animation moves actual Wiggle");P.reduceFlashes=true;yield return null;Check(rt.localScale==Vector3.one&&rt.localRotation==Quaternion.identity,"reduce flashes stops real transform motion");P.reduceFlashes=false;timer.SetValue(wig,2.1f);yield return null;Check(rt.localScale!=Vector3.one||rt.localRotation!=Quaternion.identity,"motion restores after OFF");Destroy(fixture);
 P.textScale=1.75f;P.interfaceScale=1.2f;P.independentColor=true;P.reduceFlashes=true;P.SetKeyboard(P.keyboard);P.Save();string saved=JsonUtility.ToJson(P);AccessPreferences.Load();Check(JsonUtility.ToJson(P)==saved,"all vision values reload exactly");log.Add("COMPLETE runtime geometry, actual labels and transform motion; no physical perception claim");File.WriteAllLines("Logs/FinalVision/results.txt",log);EditorApplication.Exit(log.Any(t=>t.StartsWith("FAIL"))?1:0);
 }
}
public static class FinalVisionRunner {
 public static void Run(){SessionState.SetBool("FinalVision",true);SessionState.SetString("FinalVisionDir",Path.Combine(Path.GetTempPath(),"FinalVision-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(SessionState.GetBool("FinalVision",false))DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("FinalVisionDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("FinalVision",false))return;SessionState.SetBool("FinalVision",false);new GameObject("FinalVision").AddComponent<FinalVisionProbe>();}
}
